            continue
        if name not in META_FIELDS:
            cleaned = clean_output(output.get("result", {}))
            status = output.get("status", "failed")
            if isinstance(cleaned, dict):
                cleaned["status"] = status
                filtered_actions[name] = cleaned
            else:
                filtered_actions[name] = {"result": cleaned, "status": status}
    return filtered_actions

