    # Max depth to avoid infinite loop, incase if something goes wrong.
    if depth > MAX_DEPTH:
        return

    ENRICHMENT_RAW_DATA_KEY = "enrichment_raw_data"
    if isinstance(obj, dict):
        # Remove enrichment_raw_data if present at current level
        if ENRICHMENT_RAW_DATA_KEY in obj:
            del obj[ENRICHMENT_RAW_DATA_KEY]
        # Recurse into all values
        keys = list(obj.keys())
        for key in keys:
            value = obj.get(key)
            if isinstance(value, (dict, list)):
                obj[key] = remove_enrichment_data(value, depth + 1)
        return obj
